import numpy as np


class EliteCauchyArchiveDE:
    """
    Feasibility-first current-to-pbest DE on a [0,1]^d encoding with:
      * decoded-point cache so duplicate candidates cost no budget,
      * elite feasible archive used to seed restarts with shrinking spread,
      * incumbent-centred local search mixing Gaussian and Cauchy moves,
        adapted by a 1/5th rule, plus pattern extrapolation along successful steps,
      * a budget-capped discrete neighbourhood sweep of every new incumbent
        (once per incumbent, triggered on stagnation),
      * type-aware discrete moves (+-1 for ordinal/binary, uniform switch for categorical).
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = dim

    def __call__(self, func):
        rng = np.random
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        d = lb.size
        vtypes = [str(t) for t in func.variable_types]
        disc = np.array([t != "continuous" for t in vtypes], dtype=bool)
        cont = ~disc
        nv = np.ones(d, dtype=int)
        for i in np.where(disc)[0]:
            nv[i] = max(1, int(func.n_values[i]))
        is_bin = np.array([t == "binary" for t in vtypes], dtype=bool)
        is_cat = np.array([t == "categorical" for t in vtypes], dtype=bool)
        span = ub - lb
        budget = self.budget
        disc_idx = np.where(disc)[0]

        used = 0
        cache = {}
        best_f, best_x = np.inf, None
        best_v, best_xv = np.inf, None
        g_key, g_u = (2, np.inf), None
        archive = []  # list of (f, u) feasible elites, sorted by f
        ARCH_MAX = 12
        ls_sig = [0.1]
        swept_keys = set()
        elite_restarts = [0]

        def snap(v):
            for j in disc_idx:
                v[j] = (min(int(v[j] * nv[j]), nv[j] - 1) + 0.5) / nv[j]
            return v

        def decode(u):
            x = np.empty(d)
            x[cont] = lb[cont] + u[cont] * span[cont]
            x[disc] = np.minimum(np.floor(u[disc] * nv[disc]), nv[disc] - 1)
            return x

        def add_archive(f, u):
            for fa, _ in archive:
                if fa == f:
                    return
            archive.append((f, u.copy()))
            archive.sort(key=lambda t: t[0])
            del archive[ARCH_MAX:]

        def evaluate(u):
            nonlocal used, best_f, best_x, best_v, best_xv, g_key, g_u
            x = decode(u)
            kx = x.tobytes()
            if kx in cache:
                return cache[kx]
            if used >= budget:
                return (1, np.inf)
            f, g = func(x)
            used += 1
            f = float(f)
            g = np.atleast_1d(np.asarray(g, dtype=float))
            g = np.nan_to_num(g, nan=1e6, posinf=1e6, neginf=0.0)
            viol = float(np.sum(np.maximum(g, 0.0)))
            if not np.isfinite(f):
                f = np.inf
                if viol == 0.0:
                    viol = 1.0
            feas = (viol == 0.0) and np.isfinite(f)
            if feas:
                key = (0, f)
                add_archive(f, u)
                if f < best_f:
                    best_f, best_x = f, x.copy()
            else:
                key = (1, viol)
                if viol < best_v:
                    best_v, best_xv = viol, x.copy()
            cache[kx] = key
            if key < g_key:
                g_key, g_u = key, u.copy()
            return key

        def lhs(n):
            perm = np.stack([rng.permutation(n) for _ in range(d)], axis=1)
            return (perm + rng.rand(n, d)) / n

        def set_disc(v, i, k):
            v[i] = (k + 0.5) / nv[i]

        def perturb(base, nvars, sig, heavy):
            v = base.copy()
            idxs = rng.choice(d, size=min(nvars, d), replace=False)
            for i in idxs:
                if cont[i]:
                    if heavy:
                        step = sig * rng.standard_cauchy()
                        step = np.clip(step, -0.5, 0.5)
                    else:
                        step = sig * rng.randn()
                    v[i] = np.clip(v[i] + step, 0.0, 1.0)
                elif nv[i] > 1:
                    k = min(int(np.floor(v[i] * nv[i])), nv[i] - 1)
                    if is_bin[i]:
                        k = 1 - k
                    elif is_cat[i]:
                        k2 = rng.randint(nv[i] - 1)
                        k = k2 + (1 if k2 >= k else 0)
                    else:
                        k = int(np.clip(k + (1 if rng.rand() < 0.5 else -1), 0, nv[i] - 1))
                    set_disc(v, i, k)
            return v

        def discrete_move(trial, i):
            if nv[i] <= 1:
                return
            if is_cat[i]:
                k = rng.randint(nv[i])
            else:
                k0 = min(int(np.floor(trial[i] * nv[i])), nv[i] - 1)
                if is_bin[i]:
                    k = 1 - k0
                else:
                    k = int(np.clip(k0 + (1 if rng.rand() < 0.5 else -1), 0, nv[i] - 1))
            set_disc(trial, i, k)

        def discrete_sweep(base, cap):
            # evaluate all single discrete-coordinate changes of base, capped by cap evals
            start = used
            for i in disc_idx:
                if nv[i] <= 1:
                    continue
                cur = min(int(np.floor(base[i] * nv[i])), nv[i] - 1)
                for k in range(nv[i]):
                    if k == cur:
                        continue
                    if used >= budget or used - start >= cap:
                        return
                    v = base.copy()
                    set_disc(v, i, k)
                    evaluate(v)

        def worst_index(K, NP):
            return max(range(NP), key=lambda j: K[j])

        NP_base = int(np.clip(6 * d, 20, 60))
        restart = 0
        while used < budget:
            NP = max(6, min(NP_base, (budget - used) // 5 if budget - used >= 30 else 6))
            mode = restart % 3
            if g_u is not None and mode == 1 and archive:
                # elite-seeded restart; spread shrinks with the number of elite restarts
                shrink = 0.7 ** elite_restarts[0]
                elite_restarts[0] += 1
                U = np.empty((NP, d))
                U[0] = g_u.copy()
                for r in range(1, NP):
                    if r >= NP - max(1, NP // 5):
                        U[r] = lhs(1)[0]
                    else:
                        _, base = archive[rng.randint(len(archive))]
                        sc = shrink * rng.choice([0.02, 0.08, 0.2])
                        U[r] = np.clip(base + sc * rng.randn(d), 0.0, 1.0)
                U = np.array([snap(u.copy()) if np.any(disc) else u for u in U])
            elif g_u is not None and mode == 2:
                # near-incumbent Gaussian cloud with shrinking spread
                sig = 0.05 * (0.7 ** elite_restarts[0])
                U = np.clip(g_u + sig * rng.randn(NP, d), 0.0, 1.0)
                U[0] = g_u.copy()
                n_div = NP // 4
                if n_div > 0:
                    U[-n_div:] = lhs(n_div)
            else:
                U = lhs(NP)
                if g_u is not None:
                    U[0] = g_u.copy()
            restart += 1

            K = []
            for i in range(NP):
                if used >= budget:
                    return self._result(best_f, best_x, best_xv)
                K.append(evaluate(U[i]))

            F = np.full(NP, 0.5)
            CR = np.full(NP, 0.9)
            stall = 0
            prev_gkey = g_key

            while used < budget:
                order = sorted(range(NP), key=lambda i: K[i])
                pool = order[:max(2, NP // 8)]
                for i in range(NP):
                    if used >= budget:
                        break
                    Fi, CRi = F[i], CR[i]
                    if rng.rand() < 0.1:
                        Fi = 0.1 + 0.9 * rng.rand()
                    if rng.rand() < 0.1:
                        CRi = rng.rand()

                    pb = pool[rng.randint(len(pool))]
                    cands = np.delete(np.arange(NP), i)
                    r1, r2 = rng.choice(cands, 2, replace=False)

                    mutant = U[i] + Fi * (U[pb] - U[i]) + Fi * (U[r1] - U[r2])
                    mutant = np.abs(mutant)
                    mutant = np.where(mutant > 1.0, 2.0 - mutant, mutant)
                    mutant = np.clip(mutant, 0.0, 1.0)

                    cross = rng.rand(d) < CRi
                    cross[rng.randint(d)] = True
                    trial = np.where(cross, mutant, U[i])

                    for j in np.where(disc & cross)[0]:
                        if rng.rand() < 0.08:
                            discrete_move(trial, j)

                    kt = evaluate(trial)
                    if kt <= K[i]:
                        U[i] = trial
                        K[i] = kt
                        F[i] = Fi
                        CR[i] = CRi

                # incumbent-centred local search (Gaussian/Cauchy + 1/5th rule + extrapolation)
                if g_u is not None and used < budget:
                    n_ls = max(4, NP // 4)
                    succ = 0
                    base_u = g_u.copy()
                    base_key = g_key
                    last_dir = None
                    for _ in range(n_ls):
                        if used >= budget:
                            break
                        r = rng.rand()
                        if r < 0.1:
                            v = base_u.copy()
                            idx = rng.choice(d, size=max(1, d // 3), replace=False)
                            v[idx] = rng.rand(len(idx))
                            snap(v)
                        else:
                            heavy = rng.rand() < 0.35
                            v = perturb(base_u, 1 + rng.randint(3), ls_sig[0], heavy)
                        kv = evaluate(v)
                        if kv < base_key:
                            succ += 1
                            last_dir = g_u - base_u
                            base_u, base_key = g_u.copy(), g_key
                        worst = worst_index(K, NP)
                        if kv < K[worst]:
                            U[worst] = v
                            K[worst] = kv

                    # multi-step pattern extrapolation along the last successful direction
                    if succ > 0 and last_dir is not None:
                        step = 1.0
                        for _ in range(3):
                            if used >= budget:
                                break
                            v = np.clip(g_u + step * last_dir * (0.5 + rng.rand()), 0.0, 1.0)
                            snap(v)
                            kv = evaluate(v)
                            worst = worst_index(K, NP)
                            if kv < K[worst]:
                                U[worst] = v
                                K[worst] = kv
                            if kv < base_key:
                                break
                            step *= 2.0

                    rate = succ / float(n_ls)
                    if rate > 0.2:
                        ls_sig[0] = min(0.3, ls_sig[0] * 1.3)
                    elif rate == 0.0:
                        ls_sig[0] = max(0.002, ls_sig[0] * 0.8)

                if g_key < prev_gkey:
                    stall = 0
                    prev_gkey = g_key
                else:
                    stall += 1

                # discrete sweep of each incumbent once, when stagnating
                inc_key = g_u.tobytes() if g_u is not None else None
                if (inc_key is not None and inc_key not in swept_keys and stall >= 8
                        and np.any(disc) and used < budget):
                    swept_keys.add(inc_key)
                    sweep_cap = min(200, max(20, (budget - used) // 10))
                    discrete_sweep(g_u, sweep_cap)
                    if g_key < prev_gkey:
                        stall = 0
                        prev_gkey = g_key
                    worst = worst_index(K, NP)
                    U[worst] = g_u.copy()
                    K[worst] = g_key

                spread = float(np.max(np.std(U, axis=0)))
                if stall >= 25 or spread < 1e-4:
                    break

        return self._result(best_f, best_x, best_xv)

    @staticmethod
    def _result(best_f, best_x, best_xv):
        if best_x is not None:
            return best_f, best_x
        return np.inf, best_xv
